// Las reglas viven en la tabla instagram_reglas: palabra, dm, publico, activa,
// boton, dm2, enlace, boton_enlace. Agregar una palabra clave es agregar una
// fila, sin tocar este codigo.
const reglas = $input.all().map(i => i.json).filter(r => r && r.palabra && r.activa !== false);

function normalizar(t) {
  return String(t || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

// La columna publico admite variantes separadas por |. Se elige una al azar:
// cien respuestas identicas en un mismo post son el patron que marca el
// antispam de Instagram.
function unaVariante(texto) {
  const partes = String(texto || "").split("|").map(s => s.trim()).filter(Boolean);
  if (!partes.length) return "";
  return partes[Math.floor(Math.random() * partes.length)];
}

// Se lee de 'Firmar el cuerpo recibido' y no del webhook: el webhook tiene dos
// salidas (GET y POST) y .first() devuelve la 0, que en un evento viene vacia.
const payload = $('Firmar el cuerpo recibido').first().json.body;
const salida = [];

if (payload && payload.object === "instagram") {
  for (const entry of payload.entry || []) {
    const cuenta = String(entry.id || "");
    const cambios = (entry.changes && entry.changes.length) ? entry.changes : [{ field: entry.field, value: entry.value }];
    for (const cambio of cambios) {
      if (cambio.field !== "comments") continue;
      const v = cambio.value || {};
      const commentId = String(v.id || v.comment_id || "");
      const autorId = String((v.from && v.from.id) || "");
      if (!commentId || !autorId) continue;
      if (autorId === cuenta) continue;
      const texto = normalizar(v.text);
      // Gana la primera que coincida: en la tabla, las frases largas van antes.
      const regla = reglas.find(r => texto.includes(normalizar(r.palabra)));
      if (!regla) continue;
      salida.push({
        json: {
          comment_id: commentId,
          usuario: String((v.from && v.from.username) || ""),
          texto: String(v.text || "").slice(0, 500),
          account_id: cuenta,
          palabra: String(regla.palabra || ""),
          mensaje_dm: String(regla.dm || ""),
          mensaje_publico: unaVariante(regla.publico),
          // Con boton vacio el directo sale como texto plano.
          boton: String(regla.boton || "")
        },
        // Sin esto los nodos HTTP de mas abajo no pueden resolver .item: la
        // entrada de este nodo son las reglas, no el comentario.
        pairedItem: { item: 0 }
      });
    }
  }
}

return salida;

// Un boton postback no llega como comentario: por eso no lo ve el nodo de al
// lado, que filtra field=comments.
// El payload es el que pusimos al enviar el boton: "enlace:<palabra>".
//
// Meta lo entrega en DOS formas distintas y hay que aceptar las dos:
//   entry[].messaging[].postback                                 <- los eventos reales
//   entry[].changes[] field=messaging_postbacks, value.postback  <- la prueba del panel
const reglas = $input.all().map(i => i.json).filter(r => r && r.palabra && r.activa !== false);

function normalizar(t) {
  return String(t || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

const payload = $('Firmar el cuerpo recibido').first().json.body;
const eventos = [];

if (payload && payload.object === "instagram") {
  for (const entry of payload.entry || []) {
    const cuenta = String(entry.id || "");
    for (const m of entry.messaging || []) {
      if (m && m.postback) eventos.push({ cuenta, sender: m.sender, postback: m.postback });
    }
    for (const c of entry.changes || []) {
      if (!c || c.field !== "messaging_postbacks") continue;
      const v = c.value || {};
      if (v.postback) eventos.push({ cuenta, sender: v.sender, postback: v.postback });
    }
  }
}

const salida = [];

for (const e of eventos) {
  const igsid = String((e.sender && e.sender.id) || "");
  // El eco de nuestros propios envios trae sender = la cuenta.
  if (!igsid || igsid === e.cuenta) continue;
  const clave = normalizar(String(e.postback.payload || "").split(":")[1] || "");
  if (!clave) continue;
  const regla = reglas.find(r => normalizar(r.palabra) === clave);
  // Sin enlace no hay nada que mandar: se descarta en silencio.
  if (!regla || !regla.enlace) continue;
  salida.push({
    json: {
      igsid,
      palabra: String(regla.palabra || ""),
      dm2: String(regla.dm2 || ""),
      enlace: String(regla.enlace || ""),
      boton_enlace: String(regla.boton_enlace || "")
    },
    pairedItem: { item: 0 }
  });
}

return salida;
